//! 7z archives made by 7-Zip, committed as fixtures (`fixtures/7zip-*.7z`, regenerated by
//! `fixtures/make-7z-fixtures.sh`). These run without 7-Zip installed.

use super::tests_sevenz::tree_files;
use super::*;
use forge_jobs::{CancelToken, Progress};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("src/archive/fixtures")
        .join(name)
}

/// The source tree the fixtures were made from (see `make-7z-fixtures.sh`), by `/`-separated
/// path, sorted like `tree_files`. Folders are not included.
fn expected_files() -> Vec<(String, Vec<u8>)> {
    let mut files = vec![
        (
            "src/hello.txt".to_owned(),
            "hello 7z\n".repeat(200).into_bytes(),
        ),
        (
            "src/sub/data.bin".to_owned(),
            (0..4096u32).map(|i| ((i * 31) % 256) as u8).collect(),
        ),
        ("src/zero.txt".to_owned(), Vec::new()),
        ("src/Проект.txt".to_owned(), b"unicode name\n".to_vec()),
    ];
    files.sort();
    files
}

#[test]
fn fixtures_made_by_7zip_extract_exactly() {
    let cases = [
        ("7zip-lzma2-solid.7z", None),
        ("7zip-ppmd.7z", None),
        ("7zip-bzip2-nonsolid.7z", None),
        ("7zip-bcj2.7z", None),
        ("7zip-aes.7z", Some("secret")),
        ("7zip-aes-header.7z", Some("secret")),
    ];
    for (name, password) in cases {
        let d = tempfile::tempdir().unwrap();
        let (c, p) = (CancelToken::new(), Progress::default());
        let ctx = JobCtx::new(&c, &p);
        let opts = ExtractOptions {
            password: password.map(Password::new),
            ..Default::default()
        };
        let report = extract(&fixture(name), d.path(), &opts, None, &ctx)
            .unwrap_or_else(|e| panic!("{name}: {e:?}"));
        assert!(
            report.failed.is_empty(),
            "{name} failed: {:?}",
            report.failed
        );
        assert!(
            report.skipped.is_empty(),
            "{name} skipped: {:?}",
            report.skipped
        );
        assert!(!report.cancelled, "{name} cancelled");
        assert_eq!(
            tree_files(d.path()),
            expected_files(),
            "{name}: extracted files differ"
        );
        assert!(
            d.path().join("src/empty").is_dir(),
            "{name}: src/empty missing"
        );
    }
}

#[test]
fn fixture_methods_and_flags_are_listed() {
    let list = |name: &str| list(&fixture(name)).unwrap_or_else(|e| panic!("{name}: {e:?}"));

    let lzma2 = list("7zip-lzma2-solid.7z");
    let files: Vec<_> = lzma2
        .entries
        .iter()
        .filter(|e| !e.is_dir && e.size > 0)
        .collect();
    assert!(!files.is_empty());
    assert!(
        files.iter().all(|e| e.method.contains("LZMA2")),
        "{files:?}"
    );
    assert!(files.iter().all(|e| e.solid), "solid fixture: {files:?}");

    let ppmd = list("7zip-ppmd.7z");
    assert!(
        ppmd.entries.iter().any(|e| e.method.contains("PPMd")),
        "{:?}",
        ppmd.entries
    );

    let bzip2 = list("7zip-bzip2-nonsolid.7z");
    assert!(
        bzip2.entries.iter().any(|e| e.method.contains("BZip2")),
        "{:?}",
        bzip2.entries
    );
    assert!(
        bzip2.entries.iter().all(|e| !e.solid),
        "non-solid fixture: {:?}",
        bzip2.entries
    );

    let bcj2 = list("7zip-bcj2.7z");
    assert!(
        bcj2.entries
            .iter()
            .any(|e| e.method.contains("BCJ2") || e.method.contains("LZMA")),
        "{:?}",
        bcj2.entries
    );

    for name in ["7zip-aes.7z", "7zip-aes-header.7z"] {
        let listing = list_with_password(&fixture(name), Some(&Password::new("secret")))
            .unwrap_or_else(|e| panic!("{name}: {e:?}"));
        let files: Vec<_> = listing
            .entries
            .iter()
            .filter(|e| !e.is_dir && e.size > 0)
            .collect();
        assert!(!files.is_empty());
        assert!(
            files.iter().all(|e| e.encrypted),
            "{name}: {:?}",
            listing.entries
        );
    }
}

#[test]
fn encrypted_header_fixture_needs_the_password_to_list() {
    let path = fixture("7zip-aes-header.7z");
    match list(&path) {
        Err(CoreError::PasswordRequired(_)) => {}
        other => panic!("without a password: {other:?}"),
    }
    match list_with_password(&path, Some(&Password::new("nope"))) {
        Err(CoreError::WrongPassword(_)) => {}
        other => panic!("with a wrong password: {other:?}"),
    }
    let listing = list_with_password(&path, Some(&Password::new("secret"))).unwrap();
    assert_eq!(listing.entries.len(), 7, "names: {:?}", listing.entries);
}

#[test]
fn wrong_password_on_data_fixture_writes_nothing() {
    let archive = fixture("7zip-aes.7z");
    let (c, p) = (CancelToken::new(), Progress::default());
    let ctx = JobCtx::new(&c, &p);

    let d = tempfile::tempdir().unwrap();
    let opts = ExtractOptions {
        password: Some(Password::new("nope")),
        ..Default::default()
    };
    match extract(&archive, d.path(), &opts, None, &ctx) {
        Err(CoreError::WrongPassword(_)) => {}
        other => panic!("wrong password: {other:?}"),
    }
    assert!(
        fs::read_dir(d.path()).unwrap().next().is_none(),
        "files were written"
    );

    let d = tempfile::tempdir().unwrap();
    match extract(&archive, d.path(), &ExtractOptions::default(), None, &ctx) {
        Err(CoreError::PasswordRequired(_)) => {}
        other => panic!("no password: {other:?}"),
    }
    assert!(
        fs::read_dir(d.path()).unwrap().next().is_none(),
        "files were written"
    );
}

#[test]
fn corrupt_fixture_fails_its_test_without_blaming_the_password() {
    let (c, p) = (CancelToken::new(), Progress::default());
    let ctx = JobCtx::new(&c, &p);
    let report = test_archive(
        &fixture("7zip-corrupt.7z"),
        None,
        &ExtractLimits::default(),
        &ctx,
    )
    .expect("a corrupt archive is a report, not an error");
    assert!(!report.is_ok());
    assert!(report.failures().next().is_some());
    for f in report.failures() {
        let msg = f.error.as_deref().unwrap_or_default();
        assert!(
            !msg.to_lowercase().contains("password"),
            "{}: {msg}",
            f.name
        );
    }
}
